cd /testbed && /usr/bin/clang++-18 -x c++ -std=c++17 -O0 -g -gdwarf-5 -grecord-command-line -fdebug-macro -stdlib=libc++ -D_LIBCPP_HAS_NO_PRAGMA_SYSTEM_HEADER -DFMT_HEADER_ONLY -I include -Wl,--build-id=sha1 -o build-peeky/localized-float-repro - <<'CPP'
#include <locale>
#include <fmt/printf.h>
struct english_punct : std::numpunct<char> {
  char do_decimal_point() const override { return '.'; }
  char do_thousands_sep() const override { return ','; }
  std::string do_grouping() const override { return "\3"; }
};
int main() {
  std::locale::global(std::locale(std::locale::classic(), new english_punct));
  for (double value : {-119.921, 2194.139, -57.639, -5.980, -2.119, 0.295, 1.295}) {
    auto localized = fmt::format("{:19.3Lf}", value);
    auto plain = fmt::format("{:19.3f}", value);
    fmt::print("value={} localized=[{}] width={} plain=[{}] width={}\n", value,
               localized, localized.size(), plain, plain.size());
  }
}
