#include <locale>
#include <fmt/xchar.h>
template <typename Char> struct punct : std::numpunct<Char> {
  Char do_decimal_point() const override { return '?'; }
  Char do_thousands_sep() const override { return '~'; }
  std::string do_grouping() const override { return "\3"; }
};
int main() {
  auto loc = std::locale(std::locale::classic(), new punct<wchar_t>);
  for (double value : {0.295, 1.295, 1234.5}) {
    auto s = fmt::format(loc, L"{:19.3Lf}", value);
    fmt::print("value={} localized=[{}] width={}\n", value, std::string(s.begin(), s.end()), s.size());
  }
}
