+  EXPECT_EQ("__1?295___", fmt::format(loc, "{:_^10.3Lf}", 1.295));
+  EXPECT_EQ("_____1?295", fmt::format(loc, "{:_>10.3Lf}", 1.295));
+  EXPECT_EQ("0?295_____", fmt::format(loc, "{:_<10.3Lf}", 0.295));
+  EXPECT_EQ("__0?295___", fmt::format(loc, "{:_^10.3Lf}", 0.295));
+  EXPECT_EQ("_____0?295", fmt::format(loc, "{:_>10.3Lf}", 0.295));
+  EXPECT_EQ("     1?295", fmt::format(loc, "{:10L}", 1.295));
