+  EXPECT_EQ("     1?295", fmt::format(loc, "{:10.3Lf}", 1.295L));
+  EXPECT_EQ("     1.295",
+            fmt::format(std::locale::classic(), "{:10.3Lf}", 1.295));
+  EXPECT_EQ("     1.295", fmt::format(loc, "{:10.3f}", 1.295));
+}
+
+TEST(locale_test, localized_wdouble_alignment) {
+  auto loc = std::locale(std::locale::classic(), new numpunct<wchar_t>());
+  EXPECT_EQ(L"              0?295", fmt::format(loc, L"{:19.3Lf}", 0.295));
+  EXPECT_EQ(L"              1?295", fmt::format(loc, L"{:19.3Lf}", 1.295));
+  EXPECT_EQ(L"          2~194?139", fmt::format(loc, L"{:19.3Lf}", 2194.139));
+  EXPECT_EQ(L"1?295_____", fmt::format(loc, L"{:_<10.3Lf}", 1.295));
+  EXPECT_EQ(L"__1?295___", fmt::format(loc, L"{:_^10.3Lf}", 1.295));
